  'crm.msgCarrierStatus': { 'zh-Hans': '电信 Carrier: AT&T / SMS 已连接', en: 'Carrier: AT&T / SMS connected', ko: '통신사 Carrier: AT&T / SMS 연결됨', es: 'Operador: AT&T / SMS conectado', vi: 'Nhà mạng: AT&T / SMS đã kết nối' },
  'crm.msgScheduleBoard': { 'zh-Hans': '排期看板', en: 'Schedule board', ko: '배치 보드', es: 'Tablero de horarios', vi: 'Bảng lịch trình' },
  'crm.msgAutoReminder': { 'zh-Hans': '🤖 系统自动外发 24h 到店提醒 · 确认链接已附带', en: '🤖 Automated 24-hour arrival reminder · confirmation link attached', ko: '🤖 시스템 자동 발송 24시간 전 방문 알림 · 확인 링크 포함', es: '🤖 Recordatorio automático 24 h antes · enlace de confirmación incluido', vi: '🤖 Nhắc tự động trước 24 giờ · đã kèm liên kết xác nhận' },
  'crm.msgOptedOutNotice': { 'zh-Hans': '该客户已回复 STOP 退订短信通知', en: 'This customer replied STOP to unsubscribe from SMS', ko: '이 고객은 STOP으로 문자 수신을 거부했습니다', es: 'Este cliente respondió STOP para darse de baja de los SMS', vi: 'Khách này đã trả lời STOP để ngừng nhận tin nhắn' },
  'crm.msgOptedOutNoticeDesc': { 'zh-Hans': '根据电信法规，系统已自动阻断后续向该号码的自动短信群发。如需恢复，需客户主动回复 START。', en: 'Under telecom regulations the system automatically blocks further automated messages to this number. The customer must reply START to resume.', ko: '통신 규정에 따라 시스템이 이 번호로의 후속 자동 문자 발송을 차단했습니다. 재개하려면 고객이 직접 START로 응답해야 합니다.', es: 'Conforme a la normativa, el sistema bloquea automáticamente los envíos masivos a este número. El cliente debe responder START para reanudarlos.', vi: 'Theo quy định viễn thông, hệ thống đã tự chặn các tin nhắn tự động tiếp theo tới số này. Khách phải chủ động nhắn START để khôi phục.' },
  'crm.msgQuickReplies': { 'zh-Hans': '快捷回复话术', en: 'Quick reply phrases', ko: '빠른 답장 문구', es: 'Frases de respuesta rápida', vi: 'Câu trả lời nhanh' },
  'crm.msgQuickRepliesHint': { 'zh-Hans': '点击一键填入', en: 'Tap to insert', ko: '클릭하면 바로 입력됩니다', es: 'Toca para insertarla', vi: 'Nhấn để chèn nhanh' },
  // ── 快捷回复模板 ──────────────────────────────────────────────────────────
  // ⚠️ 这四条以前写死中文——点一下就把这段文字直接填进要发给客人的短信框。
  // 界面语言选了英文/韩文/西语/越南语，发出去的短信内容却仍是中文，
  // 这不只是界面问题，是客人真的会收到一条看不懂的短信。
  'crm.msgTemplateLateTitle': { 'zh-Hans': '到店迟到确认', en: 'Late arrival confirmed', ko: '지각 확인', es: 'Llegada tarde confirmada', vi: 'Xác nhận đến muộn' },
  'crm.msgTemplateLateText': { 'zh-Hans': '没问题！已为您在排班日历中标记延迟 10 分钟，您的技师已做好接待准备，路途注意安全！', en: 'No problem! We\'ve noted a 10-minute delay on the schedule and your therapist is ready for you. Drive safe!', ko: '문제없습니다! 예약에 10분 지연으로 표시해 두었고, 담당자가 맞이할 준비를 마쳤습니다. 안전하게 오세요!', es: '¡Sin problema! Hemos anotado un retraso de 10 minutos en el horario y tu terapeuta ya está listo. ¡Ten buen viaje!', vi: 'Không sao ạ! Chúng tôi đã ghi nhận trễ 10 phút trên lịch hẹn và kỹ thuật viên đã sẵn sàng đón bạn. Đi đường cẩn thận nhé!' },
  'crm.msgTemplateParkingTitle': { 'zh-Hans': '泊车与位置指引', en: 'Parking & directions', ko: '주차 및 위치 안내', es: 'Estacionamiento y ubicación', vi: 'Chỉ dẫn chỗ đậu xe & vị trí' },
  'crm.msgTemplateParkingText': { 'zh-Hans': '您好！本店正后方配有免费客户专属停车位，导航定位至门店后门即可直接驶入。', en: 'Hi! Free customer parking is right behind our store — just navigate to our back door and drive straight in.', ko: '안녕하세요! 매장 바로 뒤편에 무료 고객 전용 주차 공간이 있습니다. 매장 후문으로 내비게이션을 설정하시면 바로 진입하실 수 있어요.', es: '¡Hola! Justo detrás de nuestra tienda hay estacionamiento gratuito para clientes; navega hasta la puerta trasera y entra directo.', vi: 'Xin chào! Ngay phía sau cửa hàng có bãi đỗ xe miễn phí dành riêng cho khách. Bạn chỉ cần định vị đến cửa sau là vào thẳng được.' },
  'crm.msgTemplateRescheduleTitle': { 'zh-Hans': '改期协商', en: 'Reschedule request', ko: '일정 변경 협의', es: 'Negociación de reprogramación', vi: 'Trao đổi đổi lịch' },
  'crm.msgTemplateRescheduleText': { 'zh-Hans': '收到您的改期诉求，请问您方便调整至本周五下午或者周六上午吗？我们将第一时间为您锁定时段。', en: 'We got your reschedule request — would Friday afternoon or Saturday morning work for you? We\'ll lock in the slot right away.', ko: '일정 변경 요청을 확인했습니다. 이번 주 금요일 오후나 토요일 오전은 괜찮으실까요? 확인 즉시 시간을 잡아드리겠습니다.', es: 'Recibimos tu solicitud de cambio de horario. ¿Te viene bien el viernes por la tarde o el sábado por la mañana? Reservaremos el horario de inmediato.', vi: 'Chúng tôi đã nhận yêu cầu đổi lịch của bạn. Bạn có thể sắp xếp vào chiều thứ Sáu hoặc sáng thứ Bảy được không? Chúng tôi sẽ giữ chỗ ngay cho bạn.' },
  'crm.msgTemplateThanksTitle': { 'zh-Hans': '服务好评关怀', en: 'Thank-you follow-up', ko: '리뷰 감사 인사', es: 'Agradecimiento por la reseña', vi: 'Cảm ơn & chăm sóc sau dịch vụ' },
  'crm.msgTemplateThanksText': { 'zh-Hans': '非常感谢您的认可与喜爱！期待下次为您提供更加贴心专业的服务，祝您生活愉快！', en: 'Thank you so much for your kind words! We look forward to taking even better care of you next time. Have a wonderful day!', ko: '소중한 후기 정말 감사드립니다! 다음에는 더욱 세심하고 전문적인 서비스로 모시겠습니다. 좋은 하루 되세요!', es: '¡Muchas gracias por tu cariño y reconocimiento! Esperamos cuidarte aún mejor la próxima vez. ¡Que tengas un gran día!', vi: 'Cảm ơn bạn rất nhiều vì sự tin yêu! Chúng tôi mong lần sau được phục vụ bạn chu đáo và chuyên nghiệp hơn nữa. Chúc bạn một ngày tốt lành!' },
  'crm.msgReplyBody': { 'zh-Hans': '回复正文', en: 'Reply', ko: '답장 본문', es: 'Cuerpo de la respuesta', vi: 'Nội dung trả lời' },
