  'crm.msgUnlockAfter10dlc': { 'zh-Hans': '10DLC 审核通过后即可直接外发', en: 'Outbound sending unlocks once 10DLC is approved', ko: '10DLC 심사를 통과하면 바로 외부 발송이 가능합니다', es: 'El envío saliente se habilita al aprobarse el 10DLC', vi: 'Sau khi 10DLC được duyệt là có thể gửi tin ngay' },
  'crm.msgSendShortcut': { 'zh-Hans': '按 ⌘ + Enter 快速发送', en: 'Press ⌘ + Enter to send', ko: '⌘ + Enter로 빠르게 발송', es: 'Pulsa ⌘ + Intro para enviar', vi: 'Nhấn ⌘ + Enter để gửi nhanh' },
  'crm.msgLockedBy10dlc': { 'zh-Hans': '未通过 10DLC 锁定', en: 'Locked pending 10DLC approval', ko: '10DLC 미승인으로 잠김', es: 'Bloqueado hasta aprobar el 10DLC', vi: 'Bị khóa do chưa qua 10DLC' },
  'crm.msgPickThread': { 'zh-Hans': '请从左侧选择一个会话开始沟通', en: 'Select a conversation on the left to start', ko: '왼쪽에서 대화를 선택해 소통을 시작하세요', es: 'Selecciona una conversación a la izquierda para empezar', vi: 'Chọn một hội thoại bên trái để bắt đầu' },
  'crm.msgUnregisteredWalkIn': { 'zh-Hans': '未建档到店散客', en: 'Walk-in without a profile', ko: '프로필 미등록 워크인 고객', es: 'Cliente sin cita ni ficha', vi: 'Khách vãng lai chưa có hồ sơ' },
