  'crm.msgGoldMember': { 'zh-Hans': '黄金会员 · 累计 8 次到店', en: 'Gold member · 8 visits to date', ko: '골드 회원 · 누적 8회 방문', es: 'Miembro Gold · 8 visitas acumuladas', vi: 'Hội viên vàng · đã đến 8 lần' },
