  'crm.callDraftToSchedule': { 'zh-Hans': '已将「{p0}」的通话意向带入排班建单', en: 'The intent from “{p0}” has been carried into the booking form', ko: '「{p0}」의 통화 의도를 예약 등록으로 가져왔습니다', es: 'La intención de «{p0}» se ha llevado al formulario de reserva', vi: 'Đã đưa ý định từ cuộc gọi của “{p0}” vào biểu mẫu đặt lịch' },
  'crm.callDraftIgnored': { 'zh-Hans': '已标记并忽略该草案，AI 模型已吸收该反馈', en: 'Draft dismissed — the AI model has absorbed this feedback', ko: '해당 초안을 무시로 표시했으며 AI 모델이 피드백을 반영했습니다', es: 'Borrador descartado; el modelo de IA ha registrado esta indicación', vi: 'Đã bỏ qua bản nháp, mô hình AI đã tiếp nhận phản hồi' },
  'crm.callLoading': { 'zh-Hans': '正在连接智能语音专线并拉取通话留痕...', en: 'Connecting to the voice line and loading call records…', ko: '지능형 음성 전용선에 연결하고 통화 기록을 가져오는 중…', es: 'Conectando con la línea de voz y recuperando los registros…', vi: 'Đang kết nối tổng đài thoại và tải nhật ký cuộc gọi…' },
  'crm.callLoadingDesc': { 'zh-Hans': '正在同步 AI 接待逐字稿、录音音频、意向草案与预约转换率', en: 'Syncing AI transcripts, audio recordings, intent drafts and booking conversion rates', ko: 'AI 접수 스크립트, 녹음 오디오, 의도 초안, 예약 전환율을 동기화하는 중', es: 'Sincronizando transcripciones, audios, borradores de intención y tasas de conversión', vi: 'Đang đồng bộ bản ghi lời thoại AI, tệp ghi âm, bản nháp ý định và tỷ lệ chuyển đổi lịch hẹn' },
  'crm.callLoadError': { 'zh-Hans': '智能语音数据加载失败', en: 'Failed to load voice data', ko: '지능형 음성 데이터를 불러오지 못했습니다', es: 'No se pudieron cargar los datos de voz', vi: 'Không tải được dữ liệu tổng đài thoại' },
  'crm.callSwitchboardTitle': { 'zh-Hans': 'AI 智能电话接线总机', en: 'AI phone switchboard', ko: 'AI 지능형 전화 교환대', es: 'Centralita telefónica con IA', vi: 'Tổng đài điện thoại AI' },
  'crm.callAlwaysOn': { 'zh-Hans': '24/7 全天候在线接听', en: 'Answering 24/7', ko: '24시간 상시 응답', es: 'Atiende 24/7', vi: 'Trực 24/7' },
  'crm.callDedicatedLine': { 'zh-Hans': '落地专线:', en: 'Direct line:', ko: '전용 회선:', es: 'Línea directa:', vi: 'Đường dây riêng:' },
  'crm.callSwitchboardDesc': { 'zh-Hans': '自动识别客户服务意图、实时查询技师工位日历、无缝落单并外发短信确认', en: 'Recognises the caller\'s intent, checks therapist and station availability in real time, books seamlessly and sends an SMS confirmation', ko: '고객 서비스 의도를 자동 인식하고 관리사·스테이션 일정을 실시간 조회하여 끊김 없이 예약하고 확인 문자를 발송합니다', es: 'Identifica la intención del cliente, consulta en tiempo real la agenda de terapeutas y puestos, reserva sin fricción y envía la confirmación por SMS', vi: 'Tự nhận diện nhu cầu của khách, tra cứu lịch KTV và vị trí theo thời gian thực, đặt lịch liền mạch và gửi SMS xác nhận' },
