  'crm.callIgnoreEnquiryOnly': { 'zh-Hans': '客人仅咨询价格/位置，未表达预约意图', en: 'Customer only asked about price or location, with no booking intent', ko: '고객이 가격·위치만 문의했으며 예약 의사는 없었습니다', es: 'El cliente solo preguntó por precio o ubicación, sin intención de reservar', vi: 'Khách chỉ hỏi giá / địa chỉ, không có ý định đặt lịch' },
  'crm.callIgnoreOtherChannel': { 'zh-Hans': '已通过微信/前台其他渠道录入', en: 'Already entered through another channel', ko: '다른 채널(위챗·프런트 등)로 이미 등록했습니다', es: 'Ya se registró por otro canal', vi: 'Đã nhập qua kênh khác (WeChat / lễ tân)' },
