  'crm.callIgnoreSpam': { 'zh-Hans': '广告推销 / 垃圾骚扰电话', en: 'Sales or spam call', ko: '광고·스팸 전화', es: 'Llamada comercial o spam', vi: 'Cuộc gọi quảng cáo / rác' },
