  'crm.callSandboxTitle': { 'zh-Hans': 'AI 电话接听即时拨测沙盒', en: 'AI phone live test sandbox', ko: 'AI 전화 응대 실시간 테스트 샌드박스', es: 'Entorno de prueba de la línea con IA', vi: 'Sandbox thử nghiệm tổng đài AI' },
  'crm.callSandboxDesc': { 'zh-Hans': '请直接使用手机致电门店 AI 专线，体验真实 24/7 智能语音接听与落单', en: 'Call the store\'s AI line from your own phone to experience the real 24/7 voice reception and booking flow', ko: '휴대전화로 매장 AI 전용선에 직접 전화하여 실제 24시간 음성 응대와 예약 과정을 체험해 보세요', es: 'Llama con tu móvil a la línea de IA del local para experimentar la recepción de voz 24/7 y el flujo de reserva reales', vi: 'Hãy dùng điện thoại gọi trực tiếp đường dây AI của cửa hàng để trải nghiệm tổng đài thoại 24/7 và quy trình đặt lịch thật' },
  'crm.callSandboxOk': { 'zh-Hans': '我知道了', en: 'Got it', ko: '확인했습니다', es: 'Entendido', vi: 'Tôi đã hiểu' },
