  'crm.callLineCopied': { 'zh-Hans': '专线号码已复制到剪贴板', en: 'Line number copied to the clipboard', ko: '전용선 번호를 클립보드에 복사했습니다', es: 'Número de la línea copiado al portapapeles', vi: 'Đã sao chép số đường dây' },
  'crm.callCopyNumber': { 'zh-Hans': '一键复制号码', en: 'Copy the number', ko: '번호 복사', es: 'Copiar el número', vi: 'Sao chép số' },
  'crm.callTestGuide': { 'zh-Hans': '拨测说明与体验提示', en: 'Test guide and what to try', ko: '테스트 안내 및 체험 팁', es: 'Guía de prueba y sugerencias', vi: 'Hướng dẫn gọi thử và gợi ý trải nghiệm' },
  'crm.callGuide1Bold': { 'zh-Hans': '真实电话接听', en: 'Real call answering', ko: '실제 전화 응대', es: 'Atención real de llamadas', vi: 'Nghe máy thật' },
  'crm.callGuide1Body': { 'zh-Hans': '：请直接拨打上述号码，系统将由云端 AI 语音助理接听并与您进行自然语音对话。', en: '：dial the number above and a cloud AI voice assistant will answer and hold a natural conversation with you.', ko: '：위 번호로 직접 전화하시면 클라우드 AI 음성 비서가 응답하여 자연스러운 대화를 진행합니다.', es: '：marca el número anterior y un asistente de voz con IA responderá y mantendrá una conversación natural contigo.', vi: '：hãy gọi trực tiếp số trên, trợ lý giọng nói AI trên đám mây sẽ bắt máy và trò chuyện tự nhiên với bạn.' },
  'crm.callGuide2Bold': { 'zh-Hans': '意图智能识别', en: 'Intent recognition', ko: '의도 지능 인식', es: 'Reconocimiento de intención', vi: 'Nhận diện ý định thông minh' },
  'crm.callGuide2Body': { 'zh-Hans': '：您可以尝试咨询服务项目、询问技师排班空档、预约指定时间或请求改期。', en: '：try asking about services, checking a therapist\'s availability, booking a specific time or requesting a reschedule.', ko: '：서비스 문의, 관리사 빈 시간 확인, 특정 시간 예약, 일정 변경 요청 등을 시도해 보세요.', es: '：prueba a preguntar por servicios, consultar huecos de un terapeuta, reservar una hora concreta o pedir un cambio.', vi: '：bạn có thể hỏi về dịch vụ, hỏi lịch trống của KTV, đặt giờ cụ thể hoặc xin đổi lịch.' },
  'crm.callGuide3Bold': { 'zh-Hans': '自动回传排班', en: 'Automatic hand-off to the schedule', ko: '일정 자동 회신', es: 'Retorno automático a la agenda', vi: 'Tự động chuyển vào lịch' },
  'crm.callGuide3Body': { 'zh-Hans': '：通话结束后，意向将自动汇总生成在下方的「待复核预约意向草案」中并实时同步排期。', en: '：after the call ends, the intent is summarised into the “drafts awaiting review” list below and synced to the schedule in real time.', ko: '：통화가 끝나면 의도가 아래 「검토 대기 예약 의도 초안」에 자동 생성되어 일정에 실시간 반영됩니다.', es: '：al terminar la llamada, la intención se resume en la lista de «borradores pendientes» y se sincroniza con la agenda al instante.', vi: '：sau khi kết thúc cuộc gọi, ý định sẽ được tổng hợp vào mục “bản nháp chờ duyệt” bên dưới và đồng bộ lịch theo thời gian thực.' },
